parameters.jsCode:
const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  // Get Latest Readings ตอนนี้ pass ทั้ง batch context (batch_id, beer_name,
  // current_phase, prep_alerted_for_phase, start_date) และ series ทั้งเส้นมาด้วยกัน
  const batch = it.json;
  const r = it.json;

  const startDate = new Date(batch.start_date);
  const nowForAnalysis = new Date(batch.analysis_time_iso).getTime();
  const hoursSinceStart = (nowForAnalysis - startDate.getTime()) / 3600000;

  const pillSeries = Array.isArray(r.pill_series) ? r.pill_series : [];
  const controllerSeries = Array.isArray(r.controller_series) ? r.controller_series : [];
  const controlSeries = Array.isArray(r.control_series) ? r.control_series : [];

  const latestPill = pillSeries.length ? pillSeries[pillSeries.length - 1] : null;
  const latestController = controllerSeries.length ? controllerSeries[controllerSeries.length - 1] : null;

  // ── Pill เงียบ/แบตหมด → ประมาณอุณหภูมิเบียร์จากตู้ควบคุมแทน ──
  // Pill ปิดผนึกอยู่ในถัง เปลี่ยนแบตกลางคันไม่ได้ ถ้าตายต้องอยู่กับมันจนจบ batch จึงต้องให้
  // ระบบ degrade อย่างซื่อสัตย์: บอก AI ตรงๆ ว่าข้อมูลค้าง + ให้ค่าประมาณจากตู้ถ้าคำนวณได้
  // (beer ≈ ตู้ + gap ช่วงนิ่ง; ข้อมูลจริงชี้ว่าตอนตู้นิ่ง gap แม่นราว ±0.5°C)
  const PILL_STALE_THRESHOLD_H = 2;
  const MIN_FALLBACK_POINTS = 3;
  const pillStaleHours = r.pill_stale_hours != null ? Number(r.pill_stale_hours) : null;
  const pillIsStale = pillStaleHours != null && pillStaleHours > PILL_STALE_THRESHOLD_H;
  const fallbackGapC = r.fallback_gap_c != null ? Number(r.fallback_gap_c) : null;
  const fallbackPoints = Number(r.fallback_gap_points || 0);
  let estimatedBeerTempC = null;
  if (pillIsStale && fallbackGapC != null && fallbackPoints >= MIN_FALLBACK_POINTS
      && latestController && latestController.temp != null) {
    estimatedBeerTempC = Number((latestController.temp + fallbackGapC).toFixed(2));
  }
  const staleNoticeText = !pillIsStale ? '' : (
    `\n⚠️ **เซ็นเซอร์ Pill เงียบมา ${pillStaleHours.toFixed(1)} ชม.แล้ว` +
    (r.pill_battery_percent != null && Number(r.pill_battery_percent) <= 5 ? ' (แบตหมด)' : '') +
    `** — ค่า gravity/อุณหภูมิ Pill ที่ให้ไว้ด้านบนและจุดท้ายๆ ของกราฟเป็น**ข้อมูลค้าง** ห้ามถือเป็นสถานะปัจจุบัน และห้ามสรุปว่าเบียร์ "นิ่งแล้ว" จากการที่กราฟแบน (มันแบนเพราะไม่มีข้อมูลใหม่ ไม่ใช่เพราะการหมักหยุด) Pill เปลี่ยนแบตกลางคันไม่ได้เพราะถังปิดผนึก จะไม่มีข้อมูลใหม่ไปจนจบ batch\n` +
    (estimatedBeerTempC != null
      ? `**อุณหภูมิเบียร์โดยประมาณตอนนี้ ≈ ${estimatedBeerTempC.toFixed(2)}°C** (คำนวณจากตู้ควบคุม ${latestController.temp.toFixed(2)}°C + ส่วนต่างช่วงที่ระบบนิ่ง ${fallbackGapC.toFixed(2)}°C จาก ${fallbackPoints} จุด${r.fallback_gap_sd != null ? `, SD ${Number(r.fallback_gap_sd).toFixed(2)}` : ''}) — **ให้ใช้ค่าประมาณนี้แทนอุณหภูมิ Pill ในการตัดสิน diacetyl_rest/cold_crash** แต่ระบุในreasoning ว่าเป็นค่าประมาณ ไม่ใช่ค่าวัดจริง\n`
      : `**ประมาณอุณหภูมิเบียร์จากตู้ควบคุมไม่ได้** (ไม่มีช่วงที่เบียร์นิ่งพอที่ target ปัจจุบัน — เซ็นเซอร์น่าจะตายตอนกำลังไล่อุณหภูมิ) ให้ใช้อุณหภูมิตู้ควบคุมเป็นข้อมูลอ้างอิงคร่าวๆ ได้ แต่ต้องระบุความไม่แน่นอนนี้ใน reasoning และห้ามยืนยันการเปลี่ยนเฟสจากข้อมูลค้าง\n`) +
    `gravity ไม่มีทางรู้ค่าปัจจุบันได้เลย (ตู้ควบคุมวัดไม่ได้) ให้ระบุไว้ด้วยว่า gravity ที่เห็นเป็นค่าสุดท้ายก่อนเซ็นเซอร์ตาย\n`
  );

  // อัตราการเปลี่ยนอุณหภูมิ Pill ช่วง 6 ชม.ล่าสุด (°C/ชม.) เทียบจุดเก่าสุด
  // กับล่าสุดในหน้าต่างนั้น ใช้ประมาณเวลาที่จะถึง target แนะนำ (d-rest/cold
  // crash) ในขั้นตอนถัดไป ต้องมีช่วงเวลาห่างกันอย่างน้อย 1 ชม.ถึงจะเอามาคิด
  // กันเคส 2 จุดห่างกันไม่กี่นาทีทำให้ค่า extrapolate เพี้ยน
  let pillRampRateCPerHour = null;
  const sixHoursAgoTs = nowForAnalysis - 6 * 3600000;
  const recentPillPoints = pillSeries.filter(p => p.temp != null && new Date(p.t).getTime() >= sixHoursAgoTs);
  if (recentPillPoints.length >= 2) {
    const oldest = recentPillPoints[0];
    const newest = recentPillPoints[recentPillPoints.length - 1];
    const rampHoursSpan = (new Date(newest.t) - new Date(oldest.t)) / 3600000;
    if (rampHoursSpan >= 1) {
      pillRampRateCPerHour = (newest.temp - oldest.temp) / rampHoursSpan;
    }
  }

  // อุณหภูมิหมักจริงของ batch นี้ (เฉลี่ยจาก Pill ช่วง 72 ชม.แรก ก่อนจะมีการปรับ
  // อุณหภูมิเพื่อทำ diacetyl_rest/cold_crash) ใช้เป็น baseline เทียบแบบสัมพัทธ์
  // แทนเลของศาตายตัว เพราะแต่ละ batch/ยีสต์หมักที่อุณหภูมิไม่เท่ากัน
  const fermentationTempPoints = pillSeries.filter(p => {
    const hoursSincePoint = (new Date(p.t) - startDate) / 3600000;
    return hoursSincePoint >= 0 && hoursSincePoint <= 72 && p.temp != null;
  });
  const fermentationBaselineTemp = fermentationTempPoints.length
    ? Number((fermentationTempPoints.reduce((sum, p) => sum + p.temp, 0) / fermentationTempPoints.length).toFixed(2))
    : null;

  // เก็บ velocity คร่าวๆ ไว้บันทึกลง phase_log อ้างอิงเท่านั้น ไม่ได้ใช้เป็น
  // หลักฐานตัดสินเฟส เพราะ AI เห็นกราฟทั้งเส้นตรงๆ ด้านล่างอยู่แล้ว
  let loggedVelocity = null;
  if (pillSeries.length >= 2) {
    const first = pillSeries[0], last = pillSeries[pillSeries.length - 1];
    const hoursSpan = (new Date(last.t) - new Date(first.t)) / 3600000;
    if (hoursSpan > 0 && first.sg != null && last.sg != null) {
      loggedVelocity = (last.sg - first.sg) / (hoursSpan / 24);
    }
  }

  // ลด token ของกราฟที่ dump เข้า prompt (จาก audit จริงพบว่ากราฟกิน >85% ของ prompt) — ย่อ
  // format (timestamp สั้น/ปัดทศนิยม/ไม่พิมพ์ target ซ้ำ) และ downsample แบบ delta+heartbeat
  // แทนการตัดตามเวลาล้วนๆ: เก็บจุดก็ต่อเมื่อ SG/อุณหภูมิขยับเกิน threshold จากจุดที่เก็บล่าสุด
  // (ช่วงกราฟชัน เช่น high krausen/ไล่ d-rest/cold crash จะถูกเก็บเกือบทุกจุดโดยอัตโนมัติ) หรือ
  // ไม่มีจุดไหนถูกเก็บมาเกิน heartbeat (กันช่วงแบนราบ เช่น fg_stable หลายวัน หายไปจนดูไม่ออกว่านิ่ง
  // มานานแค่ไหน) เก็บ**เต็มความละเอียดเสมอในช่วง 6 ชม.ล่าสุด** (ตรงกับหน้าต่างที่ใช้คำนวณ ETA/เทรนด์
  // ปัจจุบัน กันไม่ให้ downsample กระทบตัวเลขที่คำนวณจริง) วัดผลจริงกับข้อมูล 2 batch ก่อนใช้ ลด
  // ขนาดกราฟได้ ~80% โดยรูปกราฟ (จุดเก็บมาก/น้อยตามความเคลื่อนไหวจริง) ยังครบ
  function fmtShortTs(iso) {
    const bkk = new Date(new Date(iso).getTime() + 7 * 3600000);
    const dd = String(bkk.getUTCDate()).padStart(2, '0');
    const mm = String(bkk.getUTCMonth() + 1).padStart(2, '0');
    const hh = String(bkk.getUTCHours()).padStart(2, '0');
    const min = String(bkk.getUTCMinutes()).padStart(2, '0');
    return `${dd}/${mm} ${hh}:${min}`;
  }

  function downsampleSeries(series, { sgThreshold = null, tempThreshold = 0.2, heartbeatHours = 3, watchTarget = false, fullResHours = 6, nowMs }) {
    if (series.length <= 2) return series;
    const fullResCutoffMs = nowMs - fullResHours * 3600000;
    const out = [series[0]];
    let lastKept = series[0];
    for (let i = 1; i < series.length - 1; i++) {
      const p = series[i];
      const tMs = new Date(p.t).getTime();
      if (tMs >= fullResCutoffMs) {
        out.push(p);
        lastKept = p;
        continue;
      }
      const gapH = (tMs - new Date(lastKept.t).getTime()) / 3600000;
      const sgMoved = sgThreshold != null && p.sg != null && lastKept.sg != null && Math.abs(p.sg - lastKept.sg) >= sgThreshold;
      const tempMoved = p.temp != null && lastKept.temp != null && Math.abs(p.temp - lastKept.temp) >= tempThreshold;
      const targetMoved = watchTarget && String(p.target) !== String(lastKept.target);
      if (sgMoved || tempMoved || targetMoved || gapH >= heartbeatHours) {
        out.push(p);
        lastKept = p;
      }
    }
    out.push(series[series.length - 1]);
    return out;
  }

  const nowMsForText = Date.now();
  const pillSeriesForText = downsampleSeries(pillSeries, { sgThreshold: 0.001, tempThreshold: 0.2, heartbeatHours: 3, fullResHours: 6, nowMs: nowMsForText });
  const controllerSeriesForText = downsampleSeries(controllerSeries, { tempThreshold: 0.2, heartbeatHours: 3, watchTarget: true, fullResHours: 6, nowMs: nowMsForText });

  const pillSeriesText = pillSeriesForText.length
    ? pillSeriesForText.map(p => `${fmtShortTs(p.t)} | SG=${p.sg != null ? p.sg.toFixed(4) : '-'} | ${p.temp != null ? p.temp.toFixed(2) : '-'}°C`).join('\n')
    : '(ไม่มีข้อมูล)';

  let prevTargetForText = null;
  const controllerSeriesText = controllerSeriesForText.length
    ? controllerSeriesForText.map(p => {
        const tempStr = p.temp != null ? p.temp.toFixed(2) : '-';
        const targetStr = p.target != null ? p.target.toFixed(2) : '-';
        let line = `${fmtShortTs(p.t)} | ${tempStr}°C`;
        if (targetStr !== prevTargetForText) {
          line += ` | target→${targetStr}°C`;
          prevTargetForText = targetStr;
        }
        return line;
      }).join('\n')
    : '(ไม่มีข้อมูล)';
  const controlSeriesText = controlSeries.length
    ? controlSeries.map(c => `${c.t} | เดิม ${c.old ?? '-'}°C → ใหม่ ${c.new ?? '-'}°C | โดย ${c.by ?? '-'}${c.remark ? ' | เหตุผล: ' + c.remark : ''}`).join('\n')
    : '(ไม่มีการปรับ target ด้วยมือในช่วงนี้)';

  // ข้อมูล recipe/ยีสต์จาก Brewfather (ถ้า batch นี้ผูก recipe ไว้ตอน /ferment_start)
  // แผน dry hop จากสูตร (jsonb array: {day, name, amount_g}) จัดกลุ่มตามวันให้อ่านง่าย —
  // ใช้เตือนใน prep_actions ตอนใกล้ถึงกำหนด โดยเฉพาะรอบแรก (day 2-3) ที่ต้องใส่ช่วง
  // high_krausen เพื่อ biotransformation
  const dryHops = Array.isArray(r.dry_hop_plan) ? r.dry_hop_plan : [];
  const dryHopByDay = {};
  dryHops.forEach(h => {
    (dryHopByDay[h.day] = dryHopByDay[h.day] || []).push(`${h.name} ${h.amount_g}g`);
  });
  // ตัวเลข "Day" ใน Brewfather เป็นแค่ค่าประมาณของผู้เขียนสูตร ไม่ใช่กำหนดการจริง — ผู้ใช้ยืนยัน
  // เองว่า Day 3 คือ "ประมาณช่วง high_krausen" และ Day 9 คือ "รอบ dry hop ที่สอง" เท่านั้น
  // เดิม prompt สั่งให้ AI เอาเลขนี้ไปเทียบกับจำนวนวันที่หมักมาแล้ว จึงตอบออกมาว่า "อีก ~29 ชม.
  // ถึง dry hop Day 3" ซึ่งไม่มีความหมาย และถ้าหมักช้ากว่าแผนเพราะอุณหภูมิต่ำ (กำลังเป็นอยู่จริง)
  // การเตือนตามวันที่จะสั่งใส่ hop ผิดจังหวะ — เปลี่ยนมา label ตามลำดับรอบ ให้เฟสจริงเป็นตัวสั่ง
  const dryHopDays = Object.keys(dryHopByDay).sort((a, b) => Number(a) - Number(b));
  const dryHopPlanText = dryHopDays
    .map((d, i) => `รอบที่ ${i + 1} (สูตรเขียนไว้ราว Day ${d}): ${dryHopByDay[d].join(', ')}`)
    .join('\n');
  const fermentationSteps = Array.isArray(r.fermentation_steps) ? r.fermentation_steps : [];
  const fermentationStepsText = fermentationSteps.length
    ? fermentationSteps.map(s => `${s.name || s.type}: ${s.stepTemp}°C x ${s.stepTime} วัน (${s.type})`).join('\n')
    : '(ไม่มีแผนหมักจาก recipe)';
  const recipeContextText = r.recipe_name
    ? `\nข้อมูลจากสูตร Brewfather ที่ผูกไว้กับ batch นี้ ("${r.recipe_name}", สไตล์ ${r.style_name ?? 'ไม่ระบุ'}):\n` +
      `- ยีสต์: ${r.yeast_name ?? 'ไม่ระบุ'}${r.yeast_min_temp_c != null ? ` (ช่วงอุณหภูมิที่ยีสต์นี้รองรับ: ${r.yeast_min_temp_c}-${r.yeast_max_temp_c}°C, attenuation ${r.yeast_min_attenuation ?? '-'}-${r.yeast_max_attenuation ?? r.yeast_attenuation ?? '-'}%)` : ''}\n` +
      `- แผนขั้นตอนอุณหภูมิหมักตามสูตร (ไล่ตามลำดับ):\n${fermentationStepsText}\n` +
      (dryHopPlanText ? `- แผน dry hop ตามสูตร:\n${dryHopPlanText}\n⚠️ **ตัวเลข Day ในวงเล็บเป็นแค่ค่าประมาณของผู้เขียนสูตร ห้ามนับวันจากวัน pitch แล้วเตือนตามวันที่เด็ดขาด** ตัวสั่งจริงคือเฟสที่วิเคราะห์ได้จากกราฟ: **รอบแรกใส่ตอนเข้า high_krausen จริง** (biotransformation) ส่วน**รอบท้ายใส่หลัง fg_stable** — ให้เตือนใน prep_actions พร้อมระบุ hops/ปริมาณ เมื่อเฟสปัจจุบันหรือ next_phase ตรงกับจังหวะของรอบนั้น ไม่ใช่เมื่อจำนวนวันใกล้ถึงเลขในสูตร\n` : '') +
      `⚠️ **ใช้แผนนี้เป็นข้อมูลอ้างอิงสำหรับ "ควรตั้ง target ไปเท่าไหร่" เท่านั้น ห้ามใช้จำนวนวัน/ลำดับ step ในแผนมาตัดสินว่า "ถึงเวลาเปลี่ยนเฟสหรือยัง" — การตัดสินเฟส/approaching_transition ต้องดูจากอุณหภูมิ Pill และกราฟ gravity จริงเท่านั้นเหมือนเดิมทุกประการ เพราะการหมักจริงเสร็จเร็ว/ช้ากว่าแผนได้เสมอ**\n`
    : '';

  const promptText = `คุณคือผู้เชี่ยวชาญการหมักเบียร์ (อ้างอิงหลักการจาก BJCP Yeast & Fermentation guide, John Palmer "How to Brew", Brew Your Own Fermentation Timeline) วิเคราะห์ว่า batch นี้อยู่เฟสไหนใน 7 เฟสนี้ โดยดูจาก "กราฟ" gravity/อุณหภูมิทั้งเส้นที่ให้ด้านล่าง (เรียงตามเวลา จากเก่าไปใหม่) ไม่ใช่แค่จุดเดียว:

1. lag (0-24 ชม.แรกหลัง pitch): ยีสต์ปรับตัว ยังไม่มี krausen ชัดเจน กราฟ gravity แทบไม่ขยับจากค่าเริ่มต้น แทบไม่มีผลต่างอุณหภูมิระหว่าง pill กับตู้ควบคุม

2. active_ferment (วันที่ 1-4): การหมักเริ่มแรงชัดเจน กราฟ gravity เริ่มลาดลงต่อเนื่องแต่ยังไม่ถึงช่วงชันสุด, pill เริ่มอุ่นกว่าตู้ควบคุม (ปฏิกิริยาคายความร้อน)

3. high_krausen (มักอยู่ใน 48-72 ชม.แรก): ช่วงพีคของการหมัก — กราฟ gravity ลาดชันลงเร็ว**ที่สุด**ของทั้งเส้น ผลต่างอุณหภูมิ pill-ตู้ควบคุมกว้างสุด (2-5°C) — ตอบเฟสนี้เฉพาะเมื่อประเมินว่า "ตอนนี้" ยังอยู่ในช่วงชันสุดจริง ถ้าความชันเริ่มผ่อนลงจากพีคแล้วให้เป็น slowing_ferment (เฟสนี้สำคัญต่อการเตือน dry hop รอบ biotransformation — ดูแผน dry hop ด้านล่างถ้ามี)

4. slowing_ferment: กราฟ gravity เริ่มโค้งผ่อนความชันลงจากช่วงชันสุด แต่ยังลดต่อเนื่องชัดเจน (ไม่แบนราบ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมเริ่มแคบลง

5. fg_stable: กราฟ gravity แบนราบต่อเนื่องอย่างน้อย 24-48 ชม. (ไม่ลดต่อแล้วอย่างมีนัยสำคัญ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมใกล้ 0
   ⚠️ ถ้ากราฟแบนเร็วผิดปกติ (เช่นภายใน 2-3 วันแรก) หรือแบนที่ค่าซึ่งยังสูงมากเทียบกับช่วงต้นกราฟ อาจเป็น "stuck fermentation" ให้ระบุความสงสัยไว้ใน reasoning ด้วย (ไม่ต้องเปลี่ยน phase ที่ตอบ แค่เตือนไว้)

6. diacetyl_rest: ต้องผ่าน fg_stable มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง ไม่ใช่อุณหภูมิตู้ควบคุม) ถูกยกขึ้นจาก "อุณหภูมิหมักปกติของ batch นี้" (ดูค่าที่ให้ไว้ด้านล่าง) ประมาณ +2 ถึง +4°C ค้างไว้ 2-3 วัน (จำเป็นสำหรับ lager, แนะนำสำหรับ ale ส่วนใหญ่แม้ไม่บังคับ) — **นี่คือช่วงสัมพัทธ์ ไม่ใช่ตัวเลของศาตายตัว** เพราะแต่ละ batch/ยีสต์หมักที่อุณหภูมิต่างกัน (เช่น batch ที่หมักปกติ 18°C แล้วยกไป 20-22°C ก็นับเป็น diacetyl_rest ได้ ไม่จำเป็นต้องอยู่ในช่วง 16-18°C แบบตายตัว) ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเสมอ ส่วน target/อุณหภูมิตู้ควบคุมเป็นแค่ข้อมูลเสริมว่าตู้กำลังพยายามไล่ตามคำสั่งอยู่หรือยัง (ห้ามใช้แค่ target/ตู้ยังไม่ถึงมาสรุปว่ายังไม่เข้า diacetyl_rest ทั้งที่ Pill เองถึงแล้ว)

7. cold_crash: ต้องผ่าน fg_stable (และปกติ diacetyl_rest) มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง) ลดลงเหลือ 0-4°C ค้างไว้ 1-3 วัน (ale ~1-2 วัน, lager ~2-3 วัน) — ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเช่นเดียวกับข้อ 6 (ห้ามใช้แค่ target ตู้ที่ถูกปรับลงมาสรุปว่าเข้าเฟส cold_crash แล้ว ถ้า Pill ยังไม่ถึง 0-4°C จริง ให้ถือว่ายังไม่เข้า cold_crash เต็มตัว — อยู่ diacetyl_rest หรือกำลังไล่ลงสู่ cold_crash แทน ใช้ approaching_transition=true, next_phase=cold_crash) — ถ้าอยู่ cold_crash และ Pill ค้างในช่วง 0-4°C ครบตามเกณฑ์แล้ว (ale ~1-2 วัน, lager ~2-3 วัน) ให้ตอบ batch_ready_to_package=true เพื่อแจ้งผู้ใช้ว่าพร้อมบรรจุ/แพ็คได้

หมายเหตุสำคัญ: ด้านล่างมี "ประวัติการปรับ target ด้วยมือ" ซึ่งผู้ควบคุมสั่งผ่านระบบพร้อมระบุเหตุผล (remark) เช่น "d rest" หรือ "cold crash" — ให้ใช้เป็นหลักฐานสนับสนุนสำคัญประกอบการตัดสินเฟส เพราะสะท้อนเจตนาจริงของผู้ควบคุม ไม่ใช่แค่ inference จากอุณหภูมิเพียงอย่างเดียว (เช่น ถ้าเพิ่งมีรายการปรับ target ขึ้นพร้อม remark "d rest" ให้ตีความว่ากำลังเข้าสู่ diacetyl_rest แม้ Pill จะยังไล่อุณหภูมิขึ้นไม่ถึง target ก็ตาม)

นอกจากตัดสินเฟสปัจจุบันแล้ว ให้ประมาณ "ไทม์ไลน์" ของเฟสที่ผ่านมาแล้วทั้งหมดจากกราฟทั้งเส้นด้วย (phase_timeline) — เอาแค่วันที่ (ไม่ต้องมีเวลา) เรียงจากเฟสแรกสุด (lag) ไล่ลงมาจนถึงเฟสปัจจุบัน แยก "high_krausen" (ช่วงพีคที่ SG ลดชันที่สุดของทั้งเส้น) ออกจาก "active_ferment" (ช่วงเริ่มลดก่อนถึงพีค) เป็นคนละรายการ แต่ละรายการมี summary สั้นๆ 1 บรรทัดบอกค่า SG/อุณหภูมิสำคัญของช่วงนั้น ไม่ต้องใส่เฟสที่ยังไม่เกิดขึ้นจริง (เฟสที่กำลังจะมาถึงให้ใส่แค่ใน next_phase/prep_actions ตามเดิม)

ข้อกำหนดเรื่องวันที่และความกระชับ: ทุกจุดที่ต้องระบุวันที่ (ทั้งใน phase_timeline และในข้อความ reasoning/prep_actions ถ้าต้องอ้างถึง) ให้ใช้รูปแบบ dd/mm/yyyy เท่านั้น (เช่น 17/08/2026) ห้ามใช้ชื่อเดือนภาษาอังกฤษ (Aug, Jan ฯลฯ) หรือรูปแบบ ISO (YYYY-MM-DD) เด็ดขาด และให้เขียนทุกข้อความสั้นกระชับที่สุดเท่าที่ยังสื่อความชัดเจน ไม่ใส่รายละเอียดที่ไม่จำเป็น

ข้อมูล batch "${batch.beer_name || '(ไม่ระบุชื่อ)'}":
- เริ่มหมักมาแล้ว: ${hoursSinceStart.toFixed(1)} ชั่วโมง (${(hoursSinceStart / 24).toFixed(1)} วัน)
- เฟสล่าสุดที่บันทึกไว้: ${batch.current_phase}
- อุณหภูมิ Pill (เบียร์จริง) ล่าสุด: ${latestPill && latestPill.temp != null ? latestPill.temp : 'ไม่มีข้อมูล'}°C ← ใช้ตัวนี้ตัดสิน diacetyl_rest/cold_crash เป็นหลัก
- อุณหภูมิหมักปกติของ batch นี้ (เฉลี่ย Pill ช่วง 72 ชม.แรก): ${fermentationBaselineTemp ?? 'ไม่มีข้อมูล'}°C ← baseline สำหรับเทียบว่ายกขึ้น +2 ถึง +4°C แล้วหรือยัง (diacetyl_rest)
- อุณหภูมิตู้ควบคุมล่าสุด: ${latestController && latestController.temp != null ? latestController.temp : 'ไม่มีข้อมูล'}°C (ข้อมูลเสริมเท่านั้น)
- target temperature ที่ตู้ควบคุมตั้งไว้ปัจจุบัน: ${latestController && latestController.target != null ? latestController.target : 'ไม่มีข้อมูล'}°C
- ส่วนต่างอุณหภูมิ Pill-ตู้ควบคุมช่วงที่นิ่งแล้ว (เฉลี่ยจากช่วงหลังปรับ target ล่าสุด, ${r.stable_gap_points ?? 0} จุด): ${r.stable_gap_c != null ? Number(r.stable_gap_c).toFixed(2) : 'ไม่มีข้อมูลพอ'}°C ← ใช้แปลง "อุณหภูมิ Pill ที่อยากได้" เป็น "target ที่ควรตั้งบนตู้ควบคุม" (target = pill เป้าหมาย - ส่วนต่างนี้)
