ตอบกลับเป็น JSON เท่านั้น ห้ามมีข้อความอื่นปนก่อน/หลัง รูปแบบ:
{"phase": "<lag|active_ferment|high_krausen|slowing_ferment|fg_stable|diacetyl_rest|cold_crash>", "reasoning": ["<เหตุผลข้อที่ 1 สั้นๆ ภาษาไทย อ้างอิงข้อมูลที่ให้มาประกอบ>", "<เหตุผลข้อที่ 2>", "..."], "approaching_transition": <true|false>, "next_phase": <"lag"|"active_ferment"|"high_krausen"|"slowing_ferment"|"fg_stable"|"diacetyl_rest"|"cold_crash"|null>, "prep_actions": ["<ขั้นตอนเตรียมตัวข้อที่ 1>", "..."], "phase_timeline": [{"phase": "<lag|active_ferment|high_krausen|slowing_ferment|fg_stable|diacetyl_rest|cold_crash>", "from": "<DD/MM/YYYY>", "to": "<DD/MM/YYYY>", "summary": "<คำอธิบายสั้นๆ ไม่เกิน 1 บรรทัด>"}], "recommended_pill_temp_c": <number|null>, "batch_ready_to_package": <true|false>}
reasoning และ prep_actions ต้องเป็น array ของ string สั้นๆ ไม่เกิน 4 ข้อ แต่ละข้อคือประเด็นเดียว ยาวไม่เกิน ~20 คำ ไม่ใช่ paragraph ยาวๆ phase_timeline ต้องเรียงจากเฟสแรกสุดไปเฟสปัจจุบัน ไม่ต้องใส่เฟสที่ยังไม่เกิดขึ้นจริง summary ของแต่ละช่วงยาวไม่เกิน ~12 คำ
next_phase ห้ามเป็นค่าเดียวกับ phase ที่ตอบเด็ดขาด (ถ้าตัดสินว่าเข้าเฟสนั้นแล้วจริง ไม่ใช่แค่กำลังจะเข้า ให้ approaching_transition=false, next_phase=null แทน — next_phase ใช้บอกเฟส**ถัดไป**ที่ยังไม่มาถึงเท่านั้น)
reasoning กับ approaching_transition ต้องสอดคล้องกันเสมอ: ถ้าตอบ approaching_transition=true ห้ามมีข้อความใน reasoning ที่ปฏิเสธแบบเด็ดขาดว่ายังไม่มีสัญญาณของเฟสถัดไปเลย (เช่น "ยังไม่มีสัญญาณชะลอ") — ถ้าหลักฐานยังก้ำกึ่งให้เขียนระบุทั้งสองด้าน (เช่น "พีคผ่านแล้วแต่กราฟยังชัน") หรือไม่ก็ตอบ approaching_transition=false ไปเลย
recommended_pill_temp_c: ใส่เฉพาะตอน approaching_transition เป็น true และ next_phase เป็น diacetyl_rest หรือ cold_crash เท่านั้น (นอกนั้นใส่ null) คือ \"อุณหภูมิ Pill (เบียร์จริง) ที่อยากให้ไปถึง\" สำหรับเฟสถัดไป ไม่ใช่ target ของตู้ควบคุม — ถ้ามีแผนขั้นตอนจากสูตร Brewfather ด้านบนให้ใช้ค่า stepTemp ของ step ที่ตรงกับเฟสถัดไปเป็นหลัก ถ้าไม่มีแผนจากสูตรให้ประมาณเองตามเกณฑ์เดิม (baseline+2 ถึง +4°C สำหรับ diacetyl_rest, 0-4°C สำหรับ cold_crash) — ห้ามใส่ค่านี้ (ต้องเป็น null) ถ้า prep_actions ที่ตอบมาบอกให้คงอุณหภูมิ/รอต่อไปก่อน (ยังไม่ถึงเวลาปรับจริง) ใส่เฉพาะตอนที่คิดว่าควรปรับ target บนตู้ควบคุมตอนนี้เลยเท่านั้น ไม่ใช่แค่ "กำลังจะถึง"
batch_ready_to_package: true เฉพาะเมื่อ phase เป็น cold_crash และ Pill ค้างในช่วง 0-4°C ครบระยะตามเกณฑ์แล้วเท่านั้น (นอกนั้น false เสมอ)`;

  // ABV แบบสูตรง่าย (simple formula) ที่ homebrew calculator ทั่วไปใช้ default:
  // ABV% = (OG - FG) * 131.25 — จุดแรกของ pillSeries คือ OG (นับตั้งแต่ start_date),
  // จุดล่าสุดคือ FG ปัจจุบัน (ยังไม่ใช่ FG จริงจนกว่าจะถึง fg_stable แต่คำนวณ
  // ABV คร่าวๆ ไว้ดูความคืบหน้าได้ระหว่างทาง)
  const ogSg = pillSeries.length ? pillSeries[0].sg : null;
  const currentSg = latestPill ? latestPill.sg : null;
  const abvPercent = (ogSg != null && currentSg != null)
    ? Number(((ogSg - currentSg) * 131.25).toFixed(2))
    : null;

  // ช่องว่างที่กว้างที่สุดในกราฟ Pill — บอก brewmaster ว่าข้อมูลขาดช่วงไปนานแค่ไหน
  // (ต่างจาก pill_stale_hours ที่วัดแค่ "เงียบมานานเท่าไหร่นับจากจุดสุดท้ายถึงตอนนี้")
  let maxGapHours = 0, maxGapAtIso = null;
  for (let i = 1; i < pillSeries.length; i++) {
    const gh = (new Date(pillSeries[i].t).getTime() - new Date(pillSeries[i - 1].t).getTime()) / 3600000;
    if (gh > maxGapHours) { maxGapHours = gh; maxGapAtIso = pillSeries[i - 1].t; }
  }

  results.push({
    json: {
      batch_id: batch.batch_id,
      // ข้อมูลที่ Build Brewmaster Prompt ต้องใช้ — ส่งต่อจากที่นี่เพราะ node นี้อ่านแถว SQL
      // ดิบอยู่แล้ว brewmaster จะได้ไม่ต้อง itemMatching ย้อนข้ามหลาย node กลับไปหา trigger
      brewmaster_context: {
        recipe_name: r.recipe_name ?? null,
        style_name: r.style_name ?? null,
        recipe_og: r.recipe_og ?? null,
        recipe_fg: r.recipe_fg ?? null,
        yeast_name: r.yeast_name ?? null,
        yeast_min_temp_c: r.yeast_min_temp_c ?? null,
        yeast_max_temp_c: r.yeast_max_temp_c ?? null,
        yeast_min_attenuation: r.yeast_min_attenuation ?? null,
        yeast_max_attenuation: r.yeast_max_attenuation ?? r.yeast_attenuation ?? null,
        // คำนวณเทียบช่วงยีสต์ด้วยโค้ด แล้วยื่นข้อสรุปให้เลย ไม่ให้ AI เทียบเลขเอง — เจอจริง
        // 8 ก.ย. brewmaster เขียนว่า "17.69°C ... ยังอยู่ในช่วงยีสต์รองรับ (18-25°C)" ซึ่งขัดกันเอง
        // (บทเรียนเดียวกับ ETA: อะไรที่คิดเป็นตัวเลขได้ ให้โค้ดคิด)
        yeast_range_status: (() => {
          const t = latestPill && latestPill.temp != null ? Number(latestPill.temp) : null;
          const lo = r.yeast_min_temp_c != null ? Number(r.yeast_min_temp_c) : null;
          const hi = r.yeast_max_temp_c != null ? Number(r.yeast_max_temp_c) : null;
          if (t == null || lo == null || hi == null) return null;
          if (t < lo) return `ต่ำกว่าขีดล่างของยีสต์ ${(lo - t).toFixed(2)}°C (เบียร์ ${t.toFixed(2)}°C, ยีสต์รองรับ ${lo}-${hi}°C)`;
          if (t > hi) return `สูงกว่าขีดบนของยีสต์ ${(t - hi).toFixed(2)}°C (เบียร์ ${t.toFixed(2)}°C, ยีสต์รองรับ ${lo}-${hi}°C)`;
          return `อยู่ในช่วงที่ยีสต์รองรับ (เบียร์ ${t.toFixed(2)}°C, ยีสต์รองรับ ${lo}-${hi}°C)`;
        })(),
        fermentation_steps_text: fermentationStepsText,
        dry_hop_plan_text: dryHopPlanText,
        hours_since_start: Number(hoursSinceStart.toFixed(1)),
        fermentation_baseline_temp_c: fermentationBaselineTemp,
        pill_points: pillSeries.length,
        max_gap_hours: Number(maxGapHours.toFixed(1)),
        max_gap_at_iso: maxGapAtIso
      },
      beer_name: batch.beer_name,
      current_phase: batch.current_phase,
      prep_alerted_for_phase: batch.prep_alerted_for_phase,
      gravity_sg: latestPill ? latestPill.sg : null,
      temperature_c: latestPill ? latestPill.temp : null,
      gravity_velocity: loggedVelocity,
      controller_temp_c: latestController ? latestController.temp : null,
      target_temperature_c: latestController ? latestController.target : null,
      abv_percent: abvPercent,
      recipe_id: r.recipe_id ?? null,
      stable_gap_c: r.stable_gap_c ?? null,
      stable_gap_points: r.stable_gap_points ?? 0,
      pill_time_utc: latestPill ? latestPill.t : null,
      controller_time_utc: latestController ? latestController.t : null,
      pill_ramp_rate_c_per_hour: pillRampRateCPerHour,
      pill_stale_hours: pillStaleHours,
      pill_is_stale: pillIsStale,
      pill_battery_percent: r.pill_battery_percent != null ? Number(r.pill_battery_percent) : null,
      estimated_beer_temp_c: estimatedBeerTempC,
      analysis_time_iso: new Date(nowForAnalysis).toISOString(),
      prompt: promptText
    }
  });
});
return results;

// comma ในข้อความ reasoning/prep_actions ทำให้ Postgres queryReplacement
// (comma-separated string แบบเก่าที่ node นี้ใช้) เลื่อนตำแหน่ง parameter
// ผิด จนข้อความทั้งก้อนไปตกอยู่ใน parameter ตัวเลข แล้ว insert พัง
// แทนที่ comma ด้วยรูปเต็มความกว้าง (，) กันปัญหานี้แบบไม่กระทบการอ่าน
function sanitizeForQueryReplacement(text) {
  return typeof text === 'string' ? text.replace(/,/g, '，') : text;
}
// gravity ปัด 3 ตำแหน่ง, อุณหภูมิปัด 2 ตำแหน่ง — ตัดหางทศนิยมยาวๆ จาก sensor/DB
// (เช่น 17.3434753417969) ทั้งที่จะ insert ลง phase_log และตอนไปแสดงผลใน Discord
function round(v, n) {
  return v == null ? null : Number(Number(v).toFixed(n));
}
// ---------------------------------------------------------------------
// Discord embed กลาง — สร้างที่นี่ที่เดียว แล้วให้ทั้ง Phase Analysis Cron และ
// /ferment_status ใช้ร่วมกัน (เหตุผลเดียวกับที่แยก sub-workflow นี้ออกมาแต่แรก คือ
// กันข้อความสองทางค่อยๆ เพี้ยนจากกันเวลาแก้ทีละฝั่ง)
//
// ทำไมเปลี่ยนจาก content ธรรมดาเป็น embed:
//   1) แถบสีซ้าย + title ทำให้เห็น "ขอบเขต" ของแต่ละ batch ชัดตอนมีหลาย batch
//      active พร้อมกัน — เดิมหั่นเป็น section แล้วยิงทีละข้อความ 2 batch = 12
//      ข้อความรัวติดกัน มีแค่ข้อความแรกของแต่ละ batch ที่บอกชื่อเบียร์ ท่อนที่เหลือ
//      ลอยเปล่าๆ แยกไม่ออกว่าของตัวไหน
//   2) embed รับ description 4096 / รวมทุก embed 6000 เทียบกับ content 2000 →
//      1 batch จบใน 1 ข้อความ ไม่ต้องหั่นทีละ 1900 ตัวอักษร และยิงน้อยลง 6 เท่า
//      ช่วยเรื่อง rate limit 429 ที่เคยเจอไปด้วย
// ลิมิต Discord ที่ต้องเคารพ: title 256, description 4096, field name 256,
// field value 1024, รวมทุก embed ในข้อความเดียว 6000, 25 field/embed, 10 embed/ข้อความ
const PHASE_COLORS = {
  lag: 0x95a5a6,              // เทา — ยังไม่เริ่มอะไร
  active_ferment: 0xe67e22,   // ส้ม — เริ่มแรง
  high_krausen: 0xd35400,     // ส้มเข้ม — พีค
  slowing_ferment: 0xf1c40f,  // เหลือง — ผ่อนลง
  fg_stable: 0x2ecc71,        // เขียว — นิ่งแล้ว
  diacetyl_rest: 0x3498db,    // น้ำเงิน — d-rest
  cold_crash: 0x1abc9c        // เขียวน้ำทะเล — เย็น
};
const COLOR_DEFAULT = 0x95a5a6;
const COLOR_STALE = 0xe74c3c; // แดง — Pill ตาย/ข้อมูลค้าง เหลือบตาก็รู้ว่าตัวไหนมีปัญหา

// toFixed เพื่อคุมจำนวนหลักให้คงที่เสมอ (gravity 3, อุณหภูมิ/ABV 2, ชม.ค้าง 1)
function fmtNum(v, n) {
  return v == null ? '-' : Number(v).toFixed(n);
}
// เวลาไทยรูปแบบ dd/mm/yyyy HH:mm — บวก 7 ชม.เองแล้วอ่านผ่าน getUTC* แบบเดียวกับ
// ที่ pillEtaText ใช้ในไฟล์นี้ เพื่อไม่ต้องพึ่ง luxon ให้ต่างกันสองแบบในโค้ดเดียวกัน
function fmtBkkTime(iso) {
  if (!iso) return null;
  const ms = new Date(iso).getTime();
  if (!Number.isFinite(ms)) return null;
  const d = new Date(ms + 7 * 3600000);
  const p = (x) => String(x).padStart(2, '0');
  return `${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}/${d.getUTCFullYear()} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
}
function clip(text, max) {
  const s = String(text == null ? '' : text);
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}

function buildDiscordEmbeds(d) {
  const TITLE_MAX = 256, DESC_MAX = 4096, FIELD_VALUE_MAX = 1024, TOTAL_MAX = 6000, MAX_EMBEDS = 10;
  const color = d.pill_is_stale ? COLOR_STALE : (PHASE_COLORS[d.detected_phase] ?? COLOR_DEFAULT);
  const beerName = d.beer_name || '(ไม่ระบุชื่อ)';

  const lines = [];
  lines.push('เฟส: ' + (d.detected_phase || '-')
    + (d.detected_phase !== d.previous_phase ? (' 🔔 (เปลี่ยนจาก ' + d.previous_phase + ')') : '')
    + (d.next_phase ? (' · ใกล้ ' + d.next_phase) : ''));
  if (d.pill_is_stale) {
    // Pill เงียบ = ค่า gravity/อุณหภูมิด้านล่างเป็นค่าค้างจากตอนที่ยังส่งอยู่ ไม่ใช่ค่าปัจจุบัน
    // ต้องบอกให้ชัดทุกบรรทัด กันอ่านผ่านๆ แล้วนึกว่าการหมักนิ่งแล้ว
    lines.push('⚠️ Pill เงียบมา ' + fmtNum(d.pill_stale_hours, 1) + ' ชม.'
      + (d.pill_battery_percent != null && Number(d.pill_battery_percent) <= 5 ? ' (แบตหมด)' : '')
      + ' — ค่าด้านล่างเป็นข้อมูลค้าง');
    lines.push('gravity: ' + fmtNum(d.gravity_sg, 3) + ' SG (ค้าง ไม่อัปเดตแล้ว)');
    lines.push(d.estimated_beer_temp_c != null
      ? ('อุณหภูมิเบียร์: ≈' + fmtNum(d.estimated_beer_temp_c, 2) + '°C (ประมาณจากตู้ควบคุม)')
      : ('อุณหภูมิเบียร์: ประมาณไม่ได้ (Pill ค้างที่ ' + fmtNum(d.temperature_c, 2) + '°C)'));
  } else {
    lines.push('gravity: ' + fmtNum(d.gravity_sg, 3) + ' SG · Pill: ' + fmtNum(d.temperature_c, 2) + '°C');
  }
  lines.push('ตู้ควบคุม: ' + fmtNum(d.controller_temp_c, 2) + '°C (target ' + fmtNum(d.target_temperature_c, 2) + '°C)');
  lines.push('ABV: ~' + fmtNum(d.abv_percent, 2) + '%');

  const fields = [];
  if (d.phase_timeline_text) fields.push({ name: '⏱️ ไทม์ไลน์การหมัก', value: clip(d.phase_timeline_text, FIELD_VALUE_MAX) });
  if (d.reasoning) fields.push({ name: '🧠 เหตุผล', value: clip(d.reasoning, FIELD_VALUE_MAX) });
  if (d.next_phase && d.prep_actions_text) fields.push({ name: '🔜 ใกล้เข้าเฟส ' + d.next_phase, value: clip(d.prep_actions_text, FIELD_VALUE_MAX) });
  if (d.batch_ready_to_package) {
    fields.push({ name: '🎉 พร้อมบรรจุ/แพ็คได้', value: 'cold crash ครบช่วงแล้ว — เก็บเบียร์เสร็จแล้วสั่ง /ferment_stop เพื่อปิด batch' });
  }
  if (d.recommended_controller_target_c != null) {
    fields.push({
      name: '🌡️ แนะนำตั้ง target ใหม่',
      value: clip(fmtNum(d.recommended_controller_target_c, 2) + '°C (ให้ Pill ถึง ' + fmtNum(d.recommended_pill_temp_c, 2) + '°C ตามแผน)'
        + (d.pill_eta_text ? ('\n⏱️ ' + d.pill_eta_text) : ''), FIELD_VALUE_MAX)
    });
  }

  const pillTime = fmtBkkTime(d.pill_time_utc);
  const controllerTime = fmtBkkTime(d.controller_time_utc);
  const footerParts = [];
  if (pillTime) footerParts.push('ข้อมูล Pill ' + pillTime);
  if (controllerTime) footerParts.push('ตู้ควบคุม ' + controllerTime);

  const baseTitle = clip('📋 ' + beerName, TITLE_MAX);
  const first = { title: baseTitle, color, description: clip(lines.join('\n'), DESC_MAX), fields: [] };
  if (footerParts.length) first.footer = { text: clip(footerParts.join(' · '), 2048) };

  // แตก embed ตัวใหม่เมื่อจะเกินลิมิตรวม 6000 — ปกติ batch หนึ่งใช้ ~1500 ตัวอักษร
  // จึงไม่แตะเพดานนี้ แต่กันไว้เผื่อ reasoning/ไทม์ไลน์ยาวผิดปกติ ดีกว่าให้ Discord
  // ตีกลับทั้งข้อความแล้วไม่ได้แจ้งอะไรเลย
  const embeds = [first];
  let total = (first.title || '').length + (first.description || '').length + ((first.footer && first.footer.text) || '').length;
  fields.forEach((f) => {
    const cost = f.name.length + f.value.length;
    let target = embeds[embeds.length - 1];
    if (total + cost > TOTAL_MAX || target.fields.length >= 25) {
      if (embeds.length >= MAX_EMBEDS) return;
      target = { title: clip('📋 ' + beerName + ' (ต่อ)', TITLE_MAX), color, fields: [] };
      total += target.title.length;
      embeds.push(target);
    }
    target.fields.push(f);
    total += cost;
  });
  return embeds;
}

const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  const src = $('Build AI Prompt').itemMatching(idx).json;
  let phase = null, reasoning = null;
  let approachingTransition = false, nextPhase = null, prepActionsText = '', phaseTimelineText = '', recommendedPillTempC = null, batchReadyToPackage = false;
  try {
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    let text = textBlock ? textBlock.text : undefined;
    // Claude บางทีห่อ JSON ด้วย markdown code fence (```json ... ```) ทั้งที่ prompt
    // สั่งห้ามแล้ว ตัดออกก่อน parse กันพัง (เจอจริงตอน prompt ยาวขึ้นหลังส่ง series เต็ม)
    if (text) {
      text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
      // Claude บางทีเขียนคำอธิบายนำหน้า JSON เป็นข้อความธรรมดาก่อน code fence ทั้งที่
      // prompt สั่งห้ามแล้ว (เจอจริง 18 ส.ค. ตอบขึ้นต้นด้วย "วิเคราะห์กราฟ: ..." ก่อนค่อยมี
      // ```json) ทำให้ regex ตัด fence ข้างบนไม่ทำงานเพราะ fence ไม่ได้อยู่ต้น string —
      // ตัดเอาเฉพาะช่วง { แรกสุด ถึง } ตัวสุดท้ายแทน ครอบคลุมทั้งเคสมี/ไม่มี fence และ
      // มี/ไม่มีคำนำหน้า
      const firstBrace = text.indexOf('{');
      const lastBrace = text.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace > firstBrace) {
        text = text.slice(firstBrace, lastBrace + 1);
      }
    }
    const parsed = JSON.parse(text);
    phase = parsed.phase;
    reasoning = sanitizeForQueryReplacement(Array.isArray(parsed.reasoning)
      ? parsed.reasoning.map(line => '• ' + line).join('\n')
      : String(parsed.reasoning));
    approachingTransition = parsed.approaching_transition === true;
    nextPhase = parsed.next_phase || null;
    if (nextPhase === phase) {
      // AI บางทีตอบ next_phase ซ้ำกับ phase ปัจจุบันทั้งที่ prompt สั่งห้ามแล้ว (เจอจริง 18
      // ส.ค. batch Weizen: phase=cold_crash, next_phase=cold_crash พร้อมกัน) — เชื่อแค่
      // prompt อย่างเดียวไม่พอ บังคับในโค้ดเป็นชั้นกันอีกที
      nextPhase = null;
      approachingTransition = false;
    }
    const prepActionsArr = Array.isArray(parsed.prep_actions) ? parsed.prep_actions : [];
    prepActionsText = sanitizeForQueryReplacement(prepActionsArr.map(a => '• ' + a).join('\n'));
    const timelineArr = Array.isArray(parsed.phase_timeline) ? parsed.phase_timeline : [];
    phaseTimelineText = sanitizeForQueryReplacement(timelineArr.map(p => `• ${p.phase}: ${p.from} - ${p.to} | ${p.summary}`).join('\n'));
    recommendedPillTempC = typeof parsed.recommended_pill_temp_c === 'number' ? round(parsed.recommended_pill_temp_c, 2) : null;
    // guard ระดับโค้ด (แนวเดียวกับ next_phase==phase): พร้อมบรรจุได้เฉพาะตอนอยู่ cold_crash จริงเท่านั้น
    batchReadyToPackage = parsed.batch_ready_to_package === true && phase === 'cold_crash';
  } catch (e) {
    // JSON เต็มพัง (เช่น Claude ลืม escape ตัวอักษรในข้อความ ทำให้ string ใน
    // JSON ปิดไม่ครบ) แต่บางทีค่า "phase" เองยังอ่านได้ด้วย regex ตรงๆ กู้เอาไว้
    // ดีกว่าทิ้งไปเลยทั้งที่ AI ตัดสินใจแล้วจริงๆ แค่ format ตอนท้ายพัง
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    const rawText = textBlock ? textBlock.text : '';
    const phaseMatch = rawText.match(/"phase"\s*:\s*"([a-z_]+)"/);
    if (phaseMatch) {
      phase = phaseMatch[1];
      reasoning = sanitizeForQueryReplacement('⚠️ กู้ phase จาก JSON ที่ไม่สมบูรณ์ (regex fallback, ' + String(e) + ')');
    } else {
      phase = src.current_phase; // กู้อะไรไม่ได้เลย -> คงเฟสเดิมไว้ก่อน ไม่เปลี่ยนมั่ว
      reasoning = sanitizeForQueryReplacement('AI response parse error: ' + String(e));
    }
    // approachingTransition/nextPhase/prepActionsText คงค่า default (false/null/'') ไว้ ไม่เดา
  }
  // ส่ง prep alert แค่ครั้งเดียวต่อ next_phase หนึ่งค่า กัน spam ทุก 30 นาที
  // จนกว่า AI จะเปลี่ยนใจ (next_phase อื่น) หรือเฟสเปลี่ยนจริง (reset ที่ Update Batch Phase)
  const shouldSendPrepAlert = approachingTransition
    && !!nextPhase
    && nextPhase !== src.prep_alerted_for_phase;

  // target ที่ควรตั้งบนตู้ควบคุมจริง = อุณหภูมิ Pill ที่ AI แนะนำ ลบด้วยส่วนต่าง Pill-ตู้ควบคุม
  // ช่วงนิ่ง (stable_gap_c) เพราะ Pill (เบียร์จริง) กับตู้ควบคุม (อากาศ) มักมีส่วนต่างค้างอยู่
  // เสมอแม้ตอนนิ่งแล้ว ถ้าไม่มีข้อมูลส่วนต่างพอ (ยังไม่นิ่ง/เพิ่งเริ่ม batch) จะไม่แนะนำปุ่มให้
  let recommendedControllerTargetC = (recommendedPillTempC != null && src.stable_gap_c != null)
    ? round(recommendedPillTempC - src.stable_gap_c, 2)
    : null;

  // เกณฑ์ต่ำสุดที่ต่างจาก target ปัจจุบันถึงจะแนะนำ (°C) — กัน noise เล็กน้อยจากการคำนวณ
  // stable_gap_c ใหม่ทุกรอบ ทำให้แนะนำ target ที่แทบไม่ต่างจากที่ตั้งไว้แล้วซ้ำๆ (เจอจริง 18
  // ส.ค. batch Weizen: target ตั้งไว้ 1.67°C แต่แนะนำ 1.68°C แล้วรอบถัดมาแนะนำ 1.62°C อีก
  // ทั้งที่ไม่มีอะไรใหม่ให้ action จริง)
  const MIN_TARGET_CHANGE_C = 2.5;
  if (
    recommendedControllerTargetC != null &&
    src.target_temperature_c != null &&
    Math.abs(recommendedControllerTargetC - src.target_temperature_c) < MIN_TARGET_CHANGE_C
  ) {
    recommendedPillTempC = null;
    recommendedControllerTargetC = null;
  }

  // ประมาณเวลาที่ Pill จะถึงอุณหภูมิเป้าหมายที่แนะนำ จากอัตราการเปลี่ยนแปลง
  // ล่าสุด (6 ชม., คำนวณไว้ที่ Build AI Prompt) — คำนวณด้วยเลขล้วนๆ ไม่ให้ AI
  // ทายเวลา กันเพี้ยน ถ้าอัตรายังไม่ชัดหรือทิศทางไม่ตรงกับที่ต้องการปรับ
  // (เช่น อยาก d-rest แต่ Pill กำลังลดอยู่) จะบอกตรงๆ ว่ายังประมาณไม่ได้
  // แทนที่จะโชว์เลขมั่ว
  let pillEtaText = null;
  if (recommendedPillTempC != null && src.temperature_c != null) {
    const diffC = recommendedPillTempC - src.temperature_c;
    const rate = src.pill_ramp_rate_c_per_hour;
    const MIN_RATE_C_PER_HOUR = 0.05;
    if (Math.abs(diffC) < 0.05) {
      pillEtaText = null; // ใกล้ target อยู่แล้ว ไม่ต้องประมาณเวลา
    } else if (rate == null || Math.abs(rate) < MIN_RATE_C_PER_HOUR || Math.sign(rate) !== Math.sign(diffC)) {
      pillEtaText = 'ยังไม่เห็นแนวโน้มอุณหภูมิ Pill ขยับชัดเจนพอจะประมาณเวลาได้';
    } else {
      const etaHours = Math.abs(diffC) / Math.abs(rate);
      const referenceMs = src.analysis_time_iso ? new Date(src.analysis_time_iso).getTime() : Date.now();
      const bkk = new Date(referenceMs + etaHours * 3600000 + 7 * 3600000);
      const dd = String(bkk.getUTCDate()).padStart(2, '0');
      const mm = String(bkk.getUTCMonth() + 1).padStart(2, '0');
      const yyyy = bkk.getUTCFullYear();
      const hh = String(bkk.getUTCHours()).padStart(2, '0');
      const min = String(bkk.getUTCMinutes()).padStart(2, '0');
      pillEtaText = `คาดว่าจะถึงประมาณ ${dd}/${mm}/${yyyy} ${hh}:${min} (~${etaHours.toFixed(0)} ชม. ที่อัตราปัจจุบัน ~${Math.abs(rate).toFixed(2)}°C/ชม.)`;
    }
  }
  // สร้าง object ผลลัพธ์ก่อน แล้วค่อยส่งตัวมันเองเข้า buildDiscordEmbeds — embed จึงอ่าน
  // field ชุดเดียวกับที่ consumer เคยอ่านไปประกอบข้อความเอง ไม่มีทางหลุดจากกัน
  const rowJson = {
      batch_id: src.batch_id,
      beer_name: src.beer_name,
      previous_phase: src.current_phase,
      detected_phase: phase,
      reasoning,
      gravity_sg: round(src.gravity_sg, 3),
      temperature_c: round(src.temperature_c, 2),
      gravity_velocity: src.gravity_velocity,
      controller_temp_c: round(src.controller_temp_c, 2),
      target_temperature_c: round(src.target_temperature_c, 2),
      abv_percent: round(src.abv_percent, 2),
      pill_time_utc: src.pill_time_utc ?? null,
      pill_stale_hours: src.pill_stale_hours ?? null,
      pill_is_stale: src.pill_is_stale === true,
      pill_battery_percent: src.pill_battery_percent ?? null,
      estimated_beer_temp_c: src.estimated_beer_temp_c ?? null,
      controller_time_utc: src.controller_time_utc ?? null,
      next_phase: nextPhase,
      prep_actions_text: prepActionsText,
      phase_timeline_text: phaseTimelineText,
      should_send_prep_alert: shouldSendPrepAlert,
      recommended_pill_temp_c: recommendedPillTempC,
      recommended_controller_target_c: recommendedControllerTargetC,
      pill_eta_text: pillEtaText,
      batch_ready_to_package: batchReadyToPackage
  };
  rowJson.discord_embeds = buildDiscordEmbeds(rowJson);
  results.push({ json: rowJson });
});
return results;

// Brewmaster — agent ตัวที่สอง ถาม "คนละคำถาม" กับตัวแรก ไม่ใช่มาตรวจว่าตัวแรกตอบถูกไหม
//   ตัวแรก:      "ตอนนี้อยู่เฟสไหนใน 7 เฟส"        (ดูกราฟ)
//   brewmaster:  "สิ่งที่กำลังเกิดขึ้นดีต่อเบียร์ไหม"  (ดูสูตร/ยีสต์/สไตล์)
// **จงใจไม่ส่งกราฟ gravity/อุณหภูมิให้** — พอไม่มีข้อมูลดิบ มันจึงตัดสินเฟสเองไม่ได้ในเชิง
// โครงสร้าง สองเสียงเลยไม่ขัดกันในข้อความเดียว ซึ่งเป็นความเสี่ยงหลักของการมี AI สองตัว
// prompt จึงสั้น (~2,000 ตัวอักษร เทียบกับ ~11,000 ของตัวแรก) ค่าใช้จ่ายประมาณ $1/เดือน
const results = [];
$input.all().forEach((it, idx) => {
  const d = it.json;
  const src = $('Build AI Prompt').itemMatching(idx).json;
  const ctx = src.brewmaster_context || {};

  function num(v, n) { return v == null ? 'ไม่มีข้อมูล' : Number(v).toFixed(n); }

  const yeastLine = ctx.yeast_name
    ? `${ctx.yeast_name} (รองรับ ${num(ctx.yeast_min_temp_c, 0)}-${num(ctx.yeast_max_temp_c, 0)}°C, attenuation ${ctx.yeast_min_attenuation ?? '-'}-${ctx.yeast_max_attenuation ?? '-'}%)`
    : 'ไม่ระบุ (batch นี้ไม่ได้ผูก recipe ไว้)';

  // สรุปคุณภาพข้อมูลให้ brewmaster ประเมินความน่าเชื่อถือของทุกอย่างข้างบนได้เอง
  const dataNotes = [];
  if (d.pill_is_stale) {
    dataNotes.push(`Pill เงียบมา ${num(d.pill_stale_hours, 1)} ชม. ค่าที่เห็นเป็นข้อมูลค้าง`
      + (d.estimated_beer_temp_c != null ? ` (ประมาณอุณหภูมิจากตู้ได้ ≈${num(d.estimated_beer_temp_c, 2)}°C)` : ' และประมาณอุณหภูมิจากตู้ไม่ได้'));
  }
  if (ctx.max_gap_hours > 2) dataNotes.push(`กราฟขาดช่วงกว้างสุด ${num(ctx.max_gap_hours, 1)} ชม.`);
  if (ctx.pill_points != null && ctx.pill_points < 10) dataNotes.push(`มีจุดข้อมูลแค่ ${ctx.pill_points} จุด ยังน้อย`);
  const dataText = dataNotes.length ? dataNotes.map(x => '- ' + x).join('\n') : '- ไม่พบปัญหาคุณภาพข้อมูล';

  const prompt = `คุณคือ brewmaster ที่กำลังรีวิว batch ที่กำลังหมักอยู่ของคนอื่น หน้าที่ของคุณคือบอกว่า "สิ่งที่กำลังเกิดขึ้นดีต่อเบียร์ตัวนี้หรือไม่" ไม่ใช่การจำแนกเฟส

**ขอบเขตที่ห้ามข้าม**: มีอีกระบบหนึ่งวิเคราะห์เฟสจากกราฟ gravity/อุณหภูมิไปแล้ว คุณไม่ได้เห็นกราฟนั้นและห้ามตัดสินเฟสใหม่ ถ้าข้อมูลด้านล่างดูขัดแย้งกับเฟสที่เขาสรุปมา ให้บอกความสงสัยใน phase_doubt เท่านั้น ห้ามประกาศเฟสใหม่

ข้อมูล batch "${d.beer_name || '(ไม่ระบุชื่อ)'}":
- หมักมาแล้ว ${num(ctx.hours_since_start, 1)} ชม. (${(Number(ctx.hours_since_start || 0) / 24).toFixed(1)} วัน)
- เฟสที่ระบบวิเคราะห์ได้: ${d.detected_phase}${d.next_phase ? ` (กำลังจะเข้า ${d.next_phase})` : ''}
- เหตุผลที่เขาให้ไว้:
${d.reasoning || '(ไม่มี)'}
- อุณหภูมิเบียร์ (Pill) ล่าสุด: ${num(d.temperature_c, 2)}°C
- อุณหภูมิตู้ควบคุม: ${num(d.controller_temp_c, 2)}°C (target ที่ตั้งไว้ ${num(d.target_temperature_c, 2)}°C)
- อุณหภูมิหมักเฉลี่ยช่วง 72 ชม.แรกของ batch นี้: ${num(ctx.fermentation_baseline_temp_c, 2)}°C
- เทียบกับช่วงที่ยีสต์รองรับ (คำนวณให้แล้ว ห้ามคำนวณเอง): ${ctx.yeast_range_status || 'ไม่มีข้อมูลยีสต์'}
- ABV โดยประมาณ ณ ตอนนี้: ${num(d.abv_percent, 2)}%
${d.recommended_controller_target_c != null ? `- ระบบกำลังจะแนะนำให้ปรับ target เป็น ${num(d.recommended_controller_target_c, 2)}°C (เพื่อให้ Pill ถึง ${num(d.recommended_pill_temp_c, 2)}°C)\n` : ''}
สูตรที่ผูกไว้: ${ctx.recipe_name || 'ไม่มี'}${ctx.style_name ? ` — สไตล์ ${ctx.style_name}` : ''}
- ยีสต์: ${yeastLine}
- OG/FG ตามสูตร: ${ctx.recipe_og != null ? Number(ctx.recipe_og).toFixed(3) : '-'} / ${ctx.recipe_fg != null ? Number(ctx.recipe_fg).toFixed(3) : '-'}
- แผนอุณหภูมิตามสูตร:
${ctx.fermentation_steps_text || '(ไม่มี)'}
- แผน dry hop ตามสูตร:
${ctx.dry_hop_plan_text || '(ไม่มี)'}
  ⚠️ ตัวเลข Day เป็นแค่ค่าประมาณของผู้เขียนสูตร **ห้ามนับวันจากวัน pitch แล้วบอกว่าอีกกี่ชั่วโมงจะถึง** ตัวสั่งจริงคือเฟส: รอบแรกใส่ตอนเข้า high_krausen จริง (biotransformation) รอบท้ายใส่หลัง fg_stable

คุณภาพข้อมูลที่ใช้วิเคราะห์:
${dataText}

⚠️ ตู้ควบคุมอ่านค่าต่าง (สูง/ต่ำ) จาก target ได้ตามปกติราว ±0.5°C เพราะมันคุมแบบตัด-ต่อ ห้ามยกความต่างระดับนี้ขึ้นเป็น risk — เตือนเฉพาะตอนที่ตู้ห่างจาก target มากผิดปกติหรือไล่ไม่ถึงเป็นเวลานาน

⚠️ ค่า gravity จาก Pill เป็น **แนวโน้ม** เท่านั้น ไม่ได้ calibrate ห้ามเอาไปเทียบตรงๆ กับ OG/FG ในสูตรว่าตรงหรือไม่ตรง ให้ดูทิศทางการเปลี่ยนแปลงเท่านั้น

เรื่องการเสนอปรับอุณหภูมิ — แบ่งหน้าที่กันชัดเจน:
- ระบบที่วิเคราะห์เฟสรับผิดชอบการปรับ target **ตามแผน** (ตอนจะเข้า diacetyl_rest หรือ cold_crash)
- คุณรับผิดชอบการปรับ **เพื่อแก้ไข** เท่านั้น เช่น อุณหภูมิเบียร์หลุดออกนอกช่วงที่ยีสต์รองรับ หรือห่างจาก step ของสูตรมากจนกระทบผลลัพธ์
${d.recommended_controller_target_c != null
  ? '- **รอบนี้ระบบเสนอปรับ target อยู่แล้ว ห้ามเสนอซ้อน ให้ตอบ suggested_pill_temp_c เป็น null**'
  : '- รอบนี้ระบบไม่ได้เสนอปรับอะไร ถ้าคุณเห็นว่าควรแก้ ให้เสนอได้'}
- ถ้าเสนอ ให้ตอบเป็น **อุณหภูมิของเบียร์ (Pill) ที่อยากให้ไปถึง** ไม่ใช่ค่าที่จะตั้งบนตู้ ระบบจะแปลงเป็น target ตู้ให้เอง
- ค่าที่เสนอต้องอยู่ในช่วงที่ยีสต์รองรับ และควรอ้างอิง step ของสูตรเป็นหลัก
- ถ้าไม่มีอะไรต้องแก้จริงๆ ให้ตอบ null อย่าเสนอเพียงเพราะอยากเสนอ

ประเมิน 4 ด้านนี้:
1. คุณภาพเบียร์ที่จะได้ — อุณหภูมิที่ใช้อยู่ส่งผลต่อ ester/fusel/สไตล์อย่างไร
2. ความเสี่ยงที่จะหมักไม่จบ — ยีสต์ตกก้นก่อนเวลา, attenuation ไม่ถึง, diacetyl/acetaldehyde ค้าง, stuck fermentation
3. ความตรงกับสูตร — อุณหภูมิที่ตั้งอยู่ตรงกับ step ของสูตรและช่วงที่ยีสต์รองรับไหม, dry hop ใกล้กำหนดหรือยัง
4. ความน่าเชื่อถือของข้อมูล — ถ้าข้อมูลขาด/ค้าง ให้บอกว่ามันกระทบข้อสรุปแค่ไหน

ตอบเป็น JSON เท่านั้น ห้ามมีข้อความอื่นปนก่อน/หลัง:
{"verdict": "<ok|watch|concern>", "notes": ["<ข้อสังเกตสั้นๆ ภาษาไทย ไม่เกิน ~25 คำ>", "..."], "risks": ["<ความเสี่ยงที่เป็นรูปธรรม>", "..."], "phase_agrees": <true|false>, "phase_doubt_reason": <"<เหตุผลสั้นๆ ว่าทำไมถึงไม่เห็นด้วยกับเฟสที่เขาสรุป>"|null>, "data_quality_concern": <"<ปัญหาข้อมูลที่กระทบข้อสรุป>"|null>, "suggested_pill_temp_c": <number|null>, "suggested_reason": <"<เหตุผลสั้นๆ ว่าทำไมควรปรับไปค่านั้น>"|null>}

phase_agrees: true = เห็นด้วยกับเฟสที่ระบบสรุป (กรณีปกติ) — ตอนนั้น **phase_doubt_reason ต้องเป็น null เสมอ ห้ามเขียนข้อความยืนยันว่าไม่สงสัย** ใส่ข้อความเฉพาะตอน phase_agrees=false เท่านั้น

verdict: "ok" = ทุกอย่างเข้าทาง, "watch" = มีเรื่องต้องเฝ้าดูแต่ยังไม่ต้องทำอะไร, "concern" = มีอะไรที่ควรแก้ตอนนี้
suggested_pill_temp_c: ใส่ตัวเลขเฉพาะตอนที่เห็นว่าควรปรับจริงตามขอบเขตข้างบน นอกนั้น null และ suggested_reason ต้องเป็น null ตามไปด้วย
notes ไม่เกิน 4 ข้อ risks ไม่เกิน 3 ข้อ เขียนสั้นและเป็นรูปธรรม อ้างตัวเลขที่ให้มาประกอบเสมอ ถ้าไม่มีอะไรจะเตือนจริงๆ ให้ risks เป็น array ว่าง ห้ามแต่งเรื่องมาเติม
ถ้า batch นี้ไม่ได้ผูก recipe ไว้ ให้ประเมินเท่าที่ข้อมูลมีและระบุใน notes ว่าประเมินได้จำกัดเพราะไม่มีสูตร`;

  results.push({ json: { batch_id: d.batch_id, prompt } });
});
return results;

// รวมผล brewmaster เข้ากับผลของ agent ตัวแรก แล้วต่อ field ใหม่ท้าย embed ที่สร้างไว้แล้ว
// node นี้เป็นตัวสุดท้ายของ sub-workflow — output ของมันคือสิ่งที่ Cron/Backtest/status ได้รับ
// จึงต้องส่งทุก field เดิมของ Parse AI Response ผ่านไปครบ ห้ามตกหล่น
const VERDICT_ICON = { ok: '✅', watch: '👀', concern: '⚠️' };
const FIELD_VALUE_MAX = 1024, TOTAL_MAX = 6000;

function clip(t, max) {
  const s = String(t == null ? '' : t);
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}

const results = [];
$input.all().forEach((it, idx) => {
  // ผลของ agent ตัวแรกคือฐาน — ถ้า brewmaster พังต้องยังได้ข้อความปกติครบ
  const base = $('Parse AI Response').itemMatching(idx).json;
  const out = Object.assign({}, base);

  let bm = null;
  try {
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    let text = textBlock ? textBlock.text : undefined;
    if (text) {
      // ตัดเอาเฉพาะช่วง { แรกถึง } สุดท้าย แบบเดียวกับ Parse AI Response — ครอบคลุมทั้ง
      // เคสมี code fence และเคสที่ Claude เขียนคำนำหน้า JSON ทั้งที่ prompt สั่งห้ามแล้ว
      const a = text.indexOf('{'), b = text.lastIndexOf('}');
      if (a !== -1 && b > a) text = text.slice(a, b + 1);
      bm = JSON.parse(text);
    }
  } catch (e) {
    bm = null;
    out.brewmaster_error = String(e);
  }

  if (bm) {
    const verdict = ['ok', 'watch', 'concern'].includes(bm.verdict) ? bm.verdict : 'watch';
    const notes = Array.isArray(bm.notes) ? bm.notes.slice(0, 4) : [];
    const risks = Array.isArray(bm.risks) ? bm.risks.slice(0, 3) : [];
    out.brewmaster_verdict = verdict;
    out.brewmaster_notes_text = notes.map(n => '• ' + n).join('\n');
    out.brewmaster_risks_text = risks.map(n => '⚠️ ' + n).join('\n');
    // guard ระดับโค้ด (แนวเดียวกับ next_phase!==phase ใน Parse AI Response): โชว์ข้อความ
    // "สงสัยเรื่องเฟส" ได้เฉพาะตอนที่มันตอบ phase_agrees=false จริงๆ เท่านั้น — เจอจริง 8 ก.ย.
    // มันตอบ phase_doubt เป็นย่อหน้ายืนยันว่า "ไม่มีข้อขัดแย้งที่น่าสงสัย" ทั้งที่ prompt สั่งให้
    // ตอบ null แล้วโค้ดเอาไปแสดงใต้หัวข้อ "สงสัยเรื่องเฟส" จนอ่านแล้วขัดกันเอง
    const reason = typeof bm.phase_doubt_reason === 'string' && bm.phase_doubt_reason.trim()
      ? bm.phase_doubt_reason.trim() : null;
    out.brewmaster_phase_agrees = bm.phase_agrees !== false ? true : false;
    out.brewmaster_phase_doubt = out.brewmaster_phase_agrees ? null : reason;
    out.brewmaster_data_concern = typeof bm.data_quality_concern === 'string' && bm.data_quality_concern.trim() ? bm.data_quality_concern.trim() : null;

    // --- ข้อเสนอปรับอุณหภูมิจาก brewmaster: guard ระดับโค้ดทุกข้อ ไม่เชื่อ prompt อย่างเดียว ---
    // แบ่งหน้าที่: agent ตัวแรกดูแลการปรับ "ตามแผน" (เข้า diacetyl_rest/cold_crash) ส่วน
    // brewmaster ดูแลการปรับ "เพื่อแก้ไข" (เบียร์หลุดช่วงยีสต์/ห่างจาก step สูตร) — ช่องว่างที่
    // ตัวแรกครอบคลุมไม่ได้ด้วยโครงสร้าง เพราะกฎมันคือเสนอเฉพาะตอน approaching_transition
    const YEAST_MARGIN_C = 0;           // ต้องอยู่ในช่วงที่ยีสต์รองรับ ไม่ผ่อนผัน
    // 0.5°C คือขอบล่างที่มีความหมายจริง — ตู้คุมแบบตัด-ต่อ แกว่งรอบ target อยู่แล้วราว ±0.5°C
    // สั่งเปลี่ยนน้อยกว่านั้นจะจมไปกับ hysteresis ของตู้เอง ไม่เกิดผลจริง (ต่างจากเกณฑ์ 2.5°C
    // ของ agent ตัวแรกที่ตั้งไว้กัน noise จากการคำนวณ stable_gap_c ใหม่ทุกรอบ ซึ่งหยาบเกินไป
    // สำหรับการแก้ไขระดับ 1°C เช่นดึงเบียร์กลับเข้าช่วงยีสต์)
    const MIN_CHANGE_C = 0.5;
    const ABS_MIN_C = 0, ABS_MAX_C = 30;
    const ctx = ($('Build AI Prompt').itemMatching(idx).json || {}).brewmaster_context || {};
    let sPill = typeof bm.suggested_pill_temp_c === 'number' ? Number(bm.suggested_pill_temp_c.toFixed(2)) : null;
    let sReason = typeof bm.suggested_reason === 'string' && bm.suggested_reason.trim() ? bm.suggested_reason.trim() : null;
    let sTarget = null;
    if (sPill != null) {
      const lo = ctx.yeast_min_temp_c != null ? Number(ctx.yeast_min_temp_c) - YEAST_MARGIN_C : null;
      const hi = ctx.yeast_max_temp_c != null ? Number(ctx.yeast_max_temp_c) + YEAST_MARGIN_C : null;
      const reject =
        base.recommended_controller_target_c != null            // ตัวแรกเสนออยู่แล้ว ห้ามเสนอซ้อน
        || ['diacetyl_rest', 'cold_crash'].includes(base.detected_phase)  // เฟสที่เป็นงานตัวแรก
        || sPill < ABS_MIN_C || sPill > ABS_MAX_C
        || (lo != null && sPill < lo) || (hi != null && sPill > hi);
      if (reject) { sPill = null; sReason = null; }
    }
    if (sPill != null && base.stable_gap_c != null) {
      // แปลงเป็น target ตู้ด้วยทางเดียวกับ agent ตัวแรก (pill เป้าหมาย - ส่วนต่าง Pill-ตู้ช่วงนิ่ง)
      sTarget = Number((sPill - Number(base.stable_gap_c)).toFixed(2));
      if (base.target_temperature_c != null && Math.abs(sTarget - Number(base.target_temperature_c)) < MIN_CHANGE_C) {
        sPill = null; sReason = null; sTarget = null;
      }
    }
    out.brewmaster_suggested_pill_temp_c = sPill;
    out.brewmaster_suggested_target_c = sTarget;   // null = ยังไม่มีข้อมูล gap พอจะแปลง → ไม่มีปุ่ม
    out.brewmaster_suggested_reason = sPill != null ? sReason : null;

    const lines = [];
    if (out.brewmaster_risks_text) lines.push(out.brewmaster_risks_text);
    if (out.brewmaster_notes_text) lines.push(out.brewmaster_notes_text);
    if (out.brewmaster_phase_doubt) lines.push('❓ สงสัยเรื่องเฟส: ' + out.brewmaster_phase_doubt);
    if (out.brewmaster_data_concern) lines.push('📉 ข้อมูล: ' + out.brewmaster_data_concern);
    if (out.brewmaster_suggested_pill_temp_c != null) {
      lines.push('🌡️ เสนอปรับ: ให้เบียร์ไปถึง ' + out.brewmaster_suggested_pill_temp_c.toFixed(2) + '°C'
        + (out.brewmaster_suggested_target_c != null
            ? (' (ตั้ง target ตู้ ' + out.brewmaster_suggested_target_c.toFixed(2) + '°C)')
            : ' — ยังคำนวณ target ตู้ให้ไม่ได้ เพราะยังไม่มีช่วงที่ระบบนิ่งพอหลังปรับ target ล่าสุด')
        + (out.brewmaster_suggested_reason ? ('\n   ' + out.brewmaster_suggested_reason) : ''));
    }

    // ต่อท้าย embed ที่ Parse AI Response สร้างไว้ (deep copy กันไปเขียนทับ item ต้นทาง)
    // ถ้าจะทำให้เกินลิมิตรวม 6000 ให้แยกเป็น embed ใบใหม่แทนที่จะยัดจนถูก Discord ตีกลับ
    if (lines.length && Array.isArray(base.discord_embeds) && base.discord_embeds.length) {
      const embeds = JSON.parse(JSON.stringify(base.discord_embeds));
      const field = {
        name: (VERDICT_ICON[verdict] || '🍺') + ' ความเห็น Brew Master',
        value: clip(lines.join('\n'), FIELD_VALUE_MAX)
      };
      let total = 0;
      embeds.forEach(e => {
        total += (e.title || '').length + (e.description || '').length + ((e.footer && e.footer.text) || '').length;
        (e.fields || []).forEach(f => { total += f.name.length + f.value.length; });
      });
      const last = embeds[embeds.length - 1];
      if (total + field.name.length + field.value.length <= TOTAL_MAX && (last.fields || []).length < 25) {
        last.fields = last.fields || [];
        last.fields.push(field);
      } else if (embeds.length < 10) {
        embeds.push({ title: clip('🍺 ' + (base.beer_name || '') + ' — Brew Master', 256), color: embeds[0].color, fields: [field] });
      }
      out.discord_embeds = embeds;
    }
  }

  results.push({ json: out });
});
return results;
